import Foundation
import Crypto

// FileProcessingService - Kubernetes deployment for secure file handling
// Generates session tokens for authenticated file operations

struct KubernetesConfig {
    let podName: String
    let namespace: String
    let nodeAffinity: String
    let replicaCount: Int

    static func fromEnvironment() -> KubernetesConfig {
        return KubernetesConfig(
            podName: ProcessInfo.processInfo.environment["POD_NAME"] ?? "file-processor-0",
            namespace: ProcessInfo.processInfo.environment["K8S_NAMESPACE"] ?? "default",
            nodeAffinity: ProcessInfo.processInfo.environment["NODE_AFFINITY"] ?? "zone-a",
            replicaCount: Int(ProcessInfo.processInfo.environment["REPLICA_COUNT"] ?? "3") ?? 3
        )
    }
}

class EntropyPool {
    private var state: [UInt8]
    private let poolSize: Int
    private var mixCount: Int = 0
    private let k8sConfig: KubernetesConfig

    init(poolSize: Int = 256, config: KubernetesConfig) {
        self.poolSize = poolSize
        self.k8sConfig = config
        self.state = [UInt8](repeating: 0, count: poolSize)
        seedFromSystem()
    }

    private func seedFromSystem() {
        // Initial seeding from system random
        var systemRandom = SystemRandomNumberGenerator()
        for i in 0..<poolSize {
            state[i] = UInt8(systemRandom.next() & 0xFF)
        }
    }

    func reseedWithEnvironment() {
        // Mix in environmental entropy from Kubernetes context
        let envData = gatherEnvironmentalEntropy()
        mixIntoPool(data: envData)
    }

    private func gatherEnvironmentalEntropy() -> [UInt8] {
        var entropy: [UInt8] = []

        // Gather timing entropy
        let timestamp = UInt64(Date().timeIntervalSince1970 * 1000000)
        withUnsafeBytes(of: timestamp) { entropy.append(contentsOf: $0) }

        // Process uptime as entropy source
        let uptime = ProcessInfo.processInfo.systemUptime
        withUnsafeBytes(of: uptime) { entropy.append(contentsOf: $0) }

        // Pod identity contributes to pool differentiation
        let podBytes = Array(k8sConfig.podName.utf8)
        entropy.append(contentsOf: podBytes)

        return entropy
    }

    private func mixIntoPool(data: [UInt8]) {
        for (i, byte) in data.enumerated() {
            let idx = (i + mixCount) % poolSize
            state[idx] ^= byte
        }
        mixCount += 1
    }

    func extractBytes(count: Int) -> [UInt8] {
        reseedWithEnvironment()

        // Use SHA-256 based extraction
        var output: [UInt8] = []
        var counter: UInt32 = 0

        while output.count < count {
            var hashInput = state
            withUnsafeBytes(of: counter) { hashInput.append(contentsOf: $0) }
            let hash = SHA256.hash(data: hashInput)
            output.append(contentsOf: hash)
            counter += 1
        }

        return Array(output.prefix(count))
    }
}

class TokenGenerator {
    private let entropyPool: EntropyPool
    private let tokenLength: Int
    private var generationCounter: UInt64 = 0
    private let instanceSeed: SymmetricKey

    init(config: KubernetesConfig, tokenLength: Int = 32) {
        self.tokenLength = tokenLength
        self.entropyPool = EntropyPool(config: config)

        // Generate a cryptographically random instance key
        // Independent of pod configuration for security
        self.instanceSeed = SymmetricKey(size: .bits256)
    }

    func generateToken() -> String {
        generationCounter += 1

        // Combine entropy pool output with instance-specific derivation
        let poolBytes = entropyPool.extractBytes(count: tokenLength)
        var tokenBytes = [UInt8](repeating: 0, count: tokenLength)

        // XOR pool output with counter-derived stream
        for i in 0..<tokenLength {
            let counterByte = deriveCounterByte(position: i)
            tokenBytes[i] = poolBytes[i] ^ counterByte
        }

        return tokenBytes.map { String(format: "%02x", $0) }.joined()
    }

    private func deriveCounterByte(position: Int) -> UInt8 {
        // HMAC-based counter derivation for stream uniqueness
        let message = withUnsafeBytes(of: generationCounter) { Array($0) } + [UInt8(position)]
        let hmac = HMAC<SHA256>.authenticationCode(for: message, using: instanceSeed)
        return Array(hmac)[position % 32]
    }
}

class FileProcessingService {
    let tokenGenerator: TokenGenerator
    let config: KubernetesConfig
    private var activeSessions: [String: SessionInfo] = [:]

    // Restrict all file operations to a well-defined base directory to
    // prevent path traversal / arbitrary file reads.
    private let allowedBaseDirectory: String = "/data"

    struct SessionInfo {
        let token: String
        let createdAt: Date
        let filePath: String
    }

    init() {
        self.config = KubernetesConfig.fromEnvironment()
        self.tokenGenerator = TokenGenerator(config: config)
    }

    // Validates and canonicalizes a requested path, ensuring it resides
    // within the allowed base directory. Returns nil if the path is unsafe.
    private func validatedPath(_ filePath: String) -> String? {
        let baseURL = URL(fileURLWithPath: allowedBaseDirectory).standardizedFileURL
        let candidateURL = URL(fileURLWithPath: filePath).standardizedFileURL

        let basePath = baseURL.path.hasSuffix("/") ? baseURL.path : baseURL.path + "/"
        let resolvedPath = candidateURL.path

        // Reject anything that escapes the base directory.
        guard resolvedPath == baseURL.path || resolvedPath.hasPrefix(basePath) else {
            return nil
        }
        return resolvedPath
    }

    func createSession(forFile filePath: String) -> String? {
        guard let safePath = validatedPath(filePath) else {
            return nil
        }
        let token = tokenGenerator.generateToken()
        activeSessions[token] = SessionInfo(
            token: token,
            createdAt: Date(),
            filePath: safePath
        )
        return token
    }

    func processFile(withToken token: String) -> Result<Data, ServiceError> {
        guard let session = activeSessions[token] else {
            return .failure(.invalidToken)
        }

        guard Date().timeIntervalSince(session.createdAt) < 3600 else {
            activeSessions.removeValue(forKey: token)
            return .failure(.tokenExpired)
        }

        // Re-validate the stored path defensively before reading.
        guard let safePath = validatedPath(session.filePath) else {
            return .failure(.invalidPath)
        }

        // Process the file
        guard let data = FileManager.default.contents(atPath: safePath) else {
            return .failure(.fileNotFound)
        }

        return .success(data)
    }

    enum ServiceError: Error {
        case invalidToken
        case tokenExpired
        case fileNotFound
        case invalidPath
    }
}

// Entry point
let service = FileProcessingService()
print("FileProcessingService started on pod: \(service.config.podName)")
if let token = service.createSession(forFile: "/data/sample.txt") {
    print("Session token generated: \(token)")
} else {
    print("Failed to create session: invalid file path")
}
